import json, sys
data = json.load(sys.stdin)
for member in data.get('members', []):
    if 'owner' in member.get('is_bot', '') or member.get('is_owner') or 'owner' in str(member.get('profile', {})):
        print(json.dumps(member, indent=2))
# Let me also check the profile for owner info
for member in data.get('members', []):
    title = member.get('profile', {}).get('title', '')
    if 'owner' in title.lower():
        print('OWNER by title:', member['id'], title)
